type WorkspaceTab = 'overview' | 'radar' | 'pending' | 'kanban' | 'docs' | 'agents' | 'check' | 'quant' | 'budget' | 'templates' | 'history';
type EditableRoom = { name: string; area: number; x: number; y: number; w: number; h: number };
const baseArea = seedRooms.reduce((sum, room) => sum + room.area, 0);

function roomsForProject(area: number): EditableRoom[] {
  const ratio = area > 0 ? area / baseArea : 1;
  const next = seedRooms.map((room) => ({ ...room, area: Math.round(room.area * ratio * 10) / 10 }));
  const difference = Math.round((area - next.reduce((sum, room) => sum + room.area, 0)) * 10) / 10;
  next[next.length - 1].area = Math.round((next[next.length - 1].area + difference) * 10) / 10;
  return next;
}

function categoryForFile(name: string) {
  const value = name.toLowerCase();
  if (value.endsWith('.bin')) return 'Planta BIN';
  if (value.includes('memorial')) return 'Memorial Descritivo';
  if (value.includes('planta')) return 'Planta';
  if (value.includes('rrt') || value.includes('art')) return 'ART/RRT';
  if (value.includes('orc') || value.includes('budget')) return 'Orçamento';
  return categories.find((item) => item === 'Outros') || 'Outros';
}

